def compute(vars):
    other_associated_costs = vars["v1"]
    excluded_share_based_compensation = vars["v2"]
    total_other_associated_costs = (
        other_associated_costs + excluded_share_based_compensation
    )

    return {
        "value": total_other_associated_costs,
        "trace": {
            "other_associated_costs": other_associated_costs,
            "excluded_share_based_compensation": excluded_share_based_compensation,
            "total_other_associated_costs": total_other_associated_costs,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
